olor:#D81324;background:rgba(216,19,36,.08);border:1px solid rgba(216,19,36,.25);padding:6px 18px 6px 15px;border-radius:100px;}\n.mt-eyebrow::before{content:\"\";display:inline-block;width:22px;height:2px;background:#F59E0B;vertical-align:middle;margin-right:10px;}\n.mt-contact-rows span{display:block;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.14);}\n.mt-contact-rows span:last-child{border-bottom:none;}\n.mt-contact-rows i{color:#F59E0B;width:26px;text-align:center;margin-right:8px;}\n.mt-steps div{display:flex;gap:14px;align-items:flex-start;padding:12px 0;border-bottom:1px dashed #E2E8F0;}\n.mt-steps div:last-child{border-bottom:none;}\n.mt-steps b{flex:0 0 34px;height:34px;border-radius:50%;background:#0B2154;color:#fff;font-family:Barlow,sans-serif;display:flex;align-items:center;justify-content:center;font-size:16px;}\n.mt-card-shadow{box-shadow:0 18px 44px rgba(11,33,84,.12) !important;}\n.mt-soc a{display:inline-flex;width:38px;height:38px;border-radius:50%;border:1px solid rgba(255,255,255,.3);color:#fff !important;align-items:center;justify-content:center;margin-right:10px;font-size:16px;text-decoration:none;}\n.mt-soc a:hover{background:#D81324;border-color:#D81324;}\n.mt-flinks a{color:#CBD5E1;text-decoration:none;line-height:2;}\n.mt-flinks a:hover{color:#F59E0B;}\n.elementor-accordion-item{border:1px solid #E2E8F0 !important;border-radius:10px !important;margin-bottom:12px !important;overflow:hidden;box-shadow:0 4px 14px rgba(11,33,84,.05);}\n.elementor-accordion-item .elementor-tab-title{background:#F8FAFC !important;}\n.elementor-accordion-item .elementor-tab-title.elementor-active{background:#0B2154 !important;}\n.elementor-accordion-item .elementor-tab-title.elementor-active a{color:#fff !important;}\n/* MT FINAL SINGLE-FOOTER + BRANDS */\n.site-below-footer-wrap{display:none !important;}\n.mt-flinks a{text-decoration:none !important;}\n.mt-flinks a:hover{color:#F59E0B !important;}\n.mt-copy{margin:0;}\n.mt-copy a{color:#FDE68A;text-decoration:none;}\n.mt-copy a:hover{color:#fff;}\n.mt-brands-label{border-top:4px solid #D81324;}\n.mt-brands-label .elementor-container{min-height:0;}\n.mt-brands-strip .elementor-top-column + .elementor-top-column{border-left:1px solid rgba(245,158,11,.35);}\n@media(max-width:767px){.mt-brands-strip .elementor-top-column + .elementor-top-column{border-left:none;border-top:1px solid rgba(245,158,11,.25);padding-top:14px;}}\n/* MT PALETTE UNIFY */\n:root{--mt-navy:#0B2154;--mt-dark:#001E3D;--mt-red:#D81324;--mt-gold:#F59E0B;--mt-cream:#FDE68A;--mt-bg:#F8FAFC;}\n#ast-scroll-top{background-color:#D81324 !important;}\n.ast-builder-menu-1 .sub-menu{border-color:#D81324 !important;}\na:focus,.menu-link:focus,.elementor-button:focus{outline-color:#F59E0B !important;}\n.ast-theme-transparent-header .main-header-menu .menu-link:hover,.main-header-menu .menu-item.current-menu-item > .menu-link{color:#F59E0B !important;}\ninput:focus,textarea:focus,select:focus{border-color:#0B2154 !important;box-shadow:0 0 0 1px #0B2154 !important;}\n::selection{background:#D81324;color:#fff;}\n.elementor-widget-testimonial .elementor-testimonial__image img{border:2px solid #F59E0B;}\n.mt-flinks a:hover,.mt-copy a:hover{color:#F59E0B !important;}\n/* MT BRAND CARDS */\n.mt-brand{text-align:center;padding:22px 10px;border:1px solid rgba(245,158,11,.28);border-radius:14px;background:rgba(255,255,255,.03);transition:transform .25s ease,box-shadow .25s ease,border-color .25s ease;height:100%;}\n.mt-brand:hover{transform:translateY(-5px);border-color:#F59E0B;box-shadow:0 14px 30px rgba(0,0,0,.35),0 0 0 1px #F59E0B;}\n.mt-brand-badge{display:inline-flex;width:68px;height:68px;border-radius:50%;border:2px solid #F59E0B;color:#FDE68A;font-family:Barlow,sans-serif;font-weight:800;font-size:24px;align-items:center;justify-content:center;margin-bottom:12px;background:rgba(245,158,11,.08);}\n.mt-brand strong{display:block;color:#fff;font-family:Barlow,sans-serif;font-weight:800;font-size:17px;letter-spacing:1px;margin-bottom:4px;}\n.mt-brand small{display:block;color:#CBD5E1;font-size:12px;}\n.mt-brands-strip .elementor-top-column + .elementor-top-column{border:none !important;}\n/* MT BRAND ONE + KONTAK GAP */\n.mt-brands{border-top:4px solid #D81324;}\n.mt-brand-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:18px;max-width:1220px;margin:22px auto 0;padding:0 20px;}\n@media(max-width:921px){.mt-brand-grid{grid-template-columns:repeat(3,1fr);}}\n@media(max-width:600px){.mt-brand-grid{grid-template-columns:repeat(2,1fr);gap:14px;}}\n.mt-kontak .elementor-top-column{margin-bottom:0;}\n@media(max-width:767px){.mt-kontak .elementor-top-column{margin-left:0 !important;margin-right:0 !important;margin-bottom:20px !important;}.mt-kontak .elementor-top-column:last-child{margin-bottom:0 !important;}}\n/* MT REVAMP: tombol sebaris */\n.mt-btn-row .elementor-widget-wrap > .elementor-element.elementor-widget-button{width:auto;}\n.mt-btn-row .elementor-widget-button + .elementor-widget-button{margin-left:14px;}\n@media(max-width:767px){\n.mt-btn-row .elementor-widget-wrap > .elementor-element.elementor-widget-button{width:100%;}\n.mt-btn-row .elementor-widget-button + .elementor-widget-button{margin-left:0;margin-top:12px;}\n}\n/* MT REVAMP: matikan underline bawaan Astra di konten */\n.entry-content a,.entry-content .elementor-accordion-title{text-decoration:none !important;}\n.entry-content a:hover,.entry-content .elementor-accordion-title:hover{text-decoration:underline !important;}\n/* MT REVAMP: avatar testimoni */\n.elementor-testimonial-image img{border-radius:50%;}\n/* MT REVAMP: kartu brand terang (logo asli) di atas navy */\n.mt-brand-grid{margin:4px auto 0;}\n.mt-brand{background:#FFFFFF;border:1px solid #E2E8F0;padding:20px 12px 18px;border-radius:14px;box-shadow:0 8px 22px rgba(0,0,0,.18);}\n.mt-brand:hover{background:#FFFFFF;transform:translateY(-6px);border-color:#F59E0B;box-shadow:0 16px 34px rgba(0,0,0,.32),0 0 0 1px #F59E0B;}\n.mt-brand-logo{display:flex;align-items:center;justify-content:center;height:54px;margin-bottom:12px;}\n.mt-brand-logo img{max-height:44px;max-width:80%;width:auto;height:auto;object-fit:contain;display:block;}\n.mt-brand strong{color:#0B2154;font-size:15px;letter-spacing:1.2px;}\n.mt-brand small{color:#64748B;font-size:12px;}\n.mt-wm{position:relative;display:inline-block;font-family:Barlow,sans-serif;font-weight:800;font-size:27px;letter-spacing:2px;color:#0B2154;padding-bottom:9px;line-height:1;}\n.mt-wm::after{content:\"\";position:absolute;left:50%;transform:translateX(-50%);bottom:0;width:78%;height:3px;border-radius:2px;background:linear-gradient(90deg,#D81324,#F59E0B);}\n.mt-wm-split i{font-style:normal;color:#D81324;}\n.mt-wm-split{color:#0B2154;}\n/* MT REVAMP 2b: centering tombol hero + CTA */\n.mt-btn-row-c .elementor-widget-wrap{justify-content:center;}\n/* MT REVAMP 2b: nama testimoni & judul FAQ ke palet navy */\n.elementor-testimonial-name{color:#0B2154 !important;font-weight:800;}\n.elementor-testimonial-job{color:#64748B !important;}\n.elementor-accordion-title{color:#0B2154 !important;font-weight:700;}\n.elementor-accordion-item.elementor-active .elementor-accordion-title{color:#FFFFFF !important;}\n.elementor-accordion-icon{color:#D81324 !important;}\n.elementor-accordion-item.elementor-active .elementor-accordion-icon{color:#F59E0B !important;}\n/* MT REVAMP 2c: center tombol hero/CTA di mobile */\n@media(max-width:767px){.mt-btn-row-c .elementor-widget-button{text-align:center;}}\n\n/* MT REVAMP 2d: ikon accordion + hamburger ke palet brand, alignment tombol row */\n.elementor-widget-accordion .elementor-accordion-icon svg{fill:#D81324 !important;}\n.elementor-widget-accordion .elementor-active .elementor-accordion-icon svg{fill:#F59E0B !important;}\n.mobile-menu-toggle-icon svg{fill:#0B2154 !important;}\n.mt-btn-row .elementor-widget-button{margin-bottom:0 !important;}\n','astra','','inherit','closed','closed','','14-revision-v1','','','2026-10-03 07:21:09','2026-1